function selectElement(name){if((STATE.inventory[name]||0)<1)return;const ix=STATE.selected.indexOf(name);if(ix>=0)STATE.selected.splice(ix,1);else if(STATE.selected.length<2)STATE.selected.push(name);else STATE.selected=[STATE.selected[1],name];render()}
function mergePage(){const selected=STATE.selected.map(n=>getEl(n));let result='';if(selected.length===2&&selected[0].tier===selected[1].tier){const r=STATE.recipes[pairKey(STATE.selected[0],STATE.selected[1])];result=r?`${r.icon} ${safe(r.name)} · T${r.tier}`:'✨ New discovery!'}else result=selected.length===2?'Only elements of the same tier can merge.':'Choose two elements from your backpack.';return `<div class="page-title"><div><h1>Alchemy table</h1><p>Merge two of the same tier. Nothing crosses tiers—each tier builds the next.</p></div><span class="pill">⚗ ${STATE.crafted} discoveries</span></div><div class="two-col"><section class="content-card"><div class="tier-label">01 · Choose two matching tiers</div><div class="merge-arena"><div class="merge-slot ${selected[0]?'filled':''}">${selected[0]?`<div><span style="font-size:30px">${selected[0].icon}</span><b>${safe(selected[0].name)}</b><span>Tier ${selected[0].tier}</span></div>`:'Select element one'}</div><div class="merge-plus">+</div><div class="merge-slot ${selected[1]?'filled':''}">${selected[1]?`<div><span style="font-size:30px">${selected[1].icon}</span><b>${safe(selected[1].name)}</b><span>Tier ${selected[1].tier}</span></div>`:'Select element two'}</div></div><div class="notice">${result}<br>Tier rule: T1 + T1 → T2, T2 + T2 → T3, T3 + T3 → T4, T4 + T4 → T5.</div><button class="button" onclick="doMerge()" ${selected.length!==2?'disabled':''}>✦ Combine elements</button> <button class="button secondary" onclick="STATE.selected=[];render()">Clear</button><div class="section-head"><div><h2 style="font-size:18px">Your backpack</h2><p>Select two cards to use them.</p></div></div><div class="element-grid">${inventoryCards()}</div></section><section class="content-card"><div class="page-title"><div><h1 style="font-size:24px">Discovery journal</h1><p>Every recipe is one-of-a-kind.</p></div><span class="pill">${Object.keys(STATE.recipes).length} recipes</span></div><div class="notice">The Canopy remembers your discoveries. Combine any pair of T2 elements to create T3, then continue all the way to T5.</div><div class="recipe-list">${Object.values(STATE.recipes).slice(-12).reverse().map(r=>`<div class="recipe-item"><span style="font-size:22px">${r.icon}</span><div><strong>${safe(r.name)} <small>· T${r.tier}</small></strong><small>${r.parents.map(safe).join(' + ')}</small></div><b style="margin-left:auto">${STATE.inventory[r.name]||0}</b></div>`).join('')||'<div class="notice">Your first combination is waiting.</div>'}</div></section></div>`}
function doMerge(){if(STATE.selected.length!==2)return;const [a,b]=STATE.selected,ea=getEl(a),eb=getEl(b);if(ea.tier!==eb.tier){toast('Those tiers cannot be merged together.');return}if((STATE.inventory[a]||0)<1||(STATE.inventory[b]||0)<1){toast('Not enough elements.');return}STATE.inventory[a]--;STATE.inventory[b]--;const r=makeRecipe(a,b);STATE.inventory[r.name]=(STATE.inventory[r.name]||0)+1;STATE.discovered.add(r.name);STATE.crafted++;STATE.coins+=8;STATE.xp+=25;STATE.selected=[];levelCheck();toast(`Discovery! ${r.icon} ${r.name} · Tier ${r.tier}`);render();save()}
function indexPage(){let els=allElements().filter(e=>STATE.discovered.has(e.name));return `<div class="page-title"><div><h1>Field index</h1><p>A living record of the elements discovered across the Canopy.</p></div><span class="pill">${els.length} discovered · ${allElements().length} known</span></div><div class="notice">All possible pair recipes are generated as you go: each pair within a tier makes its own unique next-tier element. Tier ${Math.min(5,Math.max(1,...els.map(e=>e.tier)))} of 5.</div>${[1,2,3,4,5].map(t=>`<div class="tier-label">Tier ${t} · ${els.filter(e=>e.tier===t).length} discovered</div><div class="element-grid">${els.filter(e=>e.tier===t).map(e=>`<div class="element-card"><div class="el-emoji">${e.icon}</div><strong>${safe(e.name)}</strong><small>${e.custom?'Custom creation':e.recipe?`${safe(e.recipe.parents.join(' + '))}`:`${e.element} · ${e.strength||'wild'}`}</small>${STATE.inventory[e.name]?`<span class="count">${STATE.inventory[e.name]}</span>`:''}</div>`).join('')||'<div class="notice">Not discovered yet. Keep exploring and combining!</div>'}</div>`).join('')}<div class="section-head"><div><h2>Recipe branches</h2><p>Unique combinations discovered so far.</p></div></div><div class="recipe-list">${Object.values(STATE.recipes).map(r=>`<div class="recipe-item"><span>${r.icon}</span><div><strong>${safe(r.name)} · Tier ${r.tier}</strong><small>${r.parents.map(safe).join(' + ')}</small></div></div>`).join('')||'<div class="notice">No recipes yet. The first pair is yours to discover.</div>'}</div>`}
function battlePage(){const hp=Math.max(0,STATE.bossHp),php=Math.max(0,STATE.playerHp);return `<div class="page-title"><div><h1>Boss grove</h1><p>Choose an element before the encounter. Strengths and weaknesses change the tide.</p></div><span class="pill">⚔ ${STATE.wins} victories</span></div><div class="battlefield"><div class="fighter"><div class="big">🧙</div><strong>Fern Walker</strong><div class="hp player"><i style="width:${php}%"></i></div><small>${php} / 100 HP · ${STATE.selected[0]?safe(STATE.selected[0]):'no element selected'}</small></div><div style="font-size:24px;color:#edc879;z-index:1">VS</div><div class="fighter"><div class="big">${STATE.levelNo%3===0?'🐉':STATE.levelNo%3===1?'🦉':'🦌'}</div><strong>${STATE.levelNo%3===0?'Elder Bramblewing':STATE.levelNo%3===1?'Gloamroot Guardian':'Moonhart'}</strong><div class="hp"><i style="width:${hp}%"></i></div><small>${hp} / 100 HP · Weak to ${['water','air','fire'][(STATE.levelNo-1)%3]}</small></div></div><div class="battle-log" id="battlelog">${php<=0?'Catch your breath before facing the grove again.':'The grove waits. Pick a discovered element, then take your turn.'}</div><div class="section-head"><div><h2>Choose your attunement</h2><p>Strengths deal bonus damage; weaknesses are less effective.</p></div></div><div class="element-grid">${inventoryCards()}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="button" onclick="battleTurn()">⚔ Take your turn</button><button class="button secondary" onclick="restBattle()">✦ Rest · 10 ◈</button></div><div class="notice">Element cycle: Water > Fire > Air > Earth > Water. Battle is turn-based; the rival grove responds after every action.</div>`}
function battleTurn(){if(STATE.playerHp<=0||STATE.bossHp<=0){toast('Rest or begin the next encounter.');return}let selected=STATE.selected[0]||'Water',e=getEl(selected),damage=15+e.tier*5;let weakness=['Water','Air','Fire'][(STATE.levelNo-1)%3];if((e.element||e.name).toLowerCase().includes(weakness.toLowerCase()))damage*=1.8;if(e.tier>1)damage+=Math.min(25,e.tier*3);STATE.bossHp=Math.max(0,STATE.bossHp-Math.floor(damage));let msg=`${e.icon} ${selected} hits for ${Math.floor(damage)} damage.`;if(STATE.bossHp===0){STATE.wins++;STATE.coins+=45;STATE.dust+=3;STATE.xp+=90;STATE.levelNo++;STATE.bossHp=100;msg+=` Victory! +45 ◈, +3 ✧, +90 XP.`;levelCheck()}else{let hit=8+Math.floor(Math.random()*13);if((e.element||'').toLowerCase()===['fire','earth','air','water'][(STATE.levelNo-1)%4])hit=Math.floor(hit*.65);STATE.playerHp=Math.max(0,STATE.playerHp-hit);msg+=` The boss retaliates for ${hit}.`;if(STATE.playerHp===0)msg+=' Your spirit needs a rest.'}STATE.selected=[];render();$('#battlelog').textContent=msg;save()}
function restBattle(){if(STATE.coins<10){toast('You need 10 coins to rest.');return}STATE.coins-=10;STATE.playerHp=100;STATE.bossHp=100;toast('Rested up. Full health restored!');render();save()}

