 function render(){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===STATE.page));$('#coins').textContent=STATE.coins;$('#dust').textContent=STATE.dust;const f={home:homePage,explore:explorePage,merge:mergePage,index:indexPage,battle:battlePage,forge:forgePage,studio:studioPage,rank:rankPage};$('#view').innerHTML=(f[STATE.page]||homePage)();$('#sidebar').innerHTML=sidebar();}
 function sidebar(){return `<section class="profile-card"><div class="profile-top"><div class="portrait">🧙</div><div><strong>Fern Walker</strong><small>✦ ${STATE.rank} · Level ${STATE.level}</small></div></div><div class="xp-row"><span>CANOPY RENOWN</span><span>${STATE.xp % 500} / 500 XP</span></div><div class="xp-bar"><i style="width:${STATE.xp%500/5}%"></i></div><div class="stat-row"><div class="stat"><b>${STATE.discovered.size}</b><small>Found</small></div><div class="stat"><b>${STATE.wins}</b><small>Victories</small></div><div class="stat"><b>${STATE.explores}</b><small>Expeditions</small></div></div></section><section class="sidebar-card"><h3>Daily blessing</h3><div class="daily"><span class="daily-icon">🌙</span><p><strong>Moonlit gathering</strong><small>Claim your daily supplies</small></p><button class="mini-button" onclick="claimDaily()">Claim</button></div></section><section class="sidebar-card"><h3>Canopy board</h3><div class="rankline"><span>①</span><span>MossyMoth</span><b>2,840</b></div><div class="rankline"><span>②</span><span>Fern Walker</span><b>${(STATE.xp+1100).toLocaleString()}</b></div><div class="rankline"><span>③</span><span>Emberling</span><b>1,960</b></div><button class="text-link" onclick="navTo('rank')">View all rankings →</button></section><section class="sidebar-card"><h3>Soundscape</h3><div class="daily"><span class="daily-icon">${STATE.sound?'🎵':'🎶'}</span><p><strong>${STATE.sound?'Forest ambience on':'Soft forest ambience'}</strong><small>Procedural, gentle and yours</small></p><button class="mini-button" onclick="toggleSound()">${STATE.sound?'Off':'On'}</button></div></section>`}
 function homePage(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">✦ Season of the verdant dawn</div><h1>Where wild things<br>become wonder.</h1><p>Wander beneath the canopy, gather the four first elements, and discover what happens when worlds collide.</p><button class="button" onclick="navTo('explore')">Explore the forest <span>→</span></button></div><div class="hero-art"><div class="sun"></div><div class="forest-art">🌳</div></div></section><div class="section-head"><div><h2>Choose your path</h2><p>Every trail holds a little magic.</p></div><button class="text-link" onclick="navTo('explore')">Open map →</button></div><div class="forest-grid"><button class="biome" data-emoji="🌊" onclick="gather('water')"><span class="level-tag">Trail · 01</span><strong>Whispering Brook</strong><span>Water · gentle & bright</span></button><button class="biome" data-emoji="🔥" onclick="gather('fire')"><span class="level-tag">Trail · 02</span><strong>Emberglow Hollow</strong><span>Fire · warm & untamed</span></button><button class="biome" data-emoji="🍄" onclick="gather('earth')"><span class="level-tag">Trail · 03</span><strong>Mosslight Grove</strong><span>Earth · quiet & ancient</span></button></div><div class="below-grid"><section class="card"><h3>Today in the Canopy</h3><div class="quest"><div class="quest-icon">🍃</div><div class="quest-copy"><strong>Gathering hands</strong><small>Collect 5 elements · ${Math.min(5,STATE.explores)} / 5</small><div class="progress"><i style="width:${Math.min(100,STATE.explores*20)}%"></i></div></div><span class="reward">+35 ◈</span></div><div class="quest"><div class="quest-icon">⚗️</div><div class="quest-copy"><strong>Little alchemist</strong><small>Discover your first new element</small><div class="progress"><i style="width:${STATE.crafted?100:0}%"></i></div></div><span class="reward">+50 XP</span></div></section><section class="card"><h3>First discoveries</h3><div class="recipe-list"><div class="recipe-item"><span>🌊 + 🔥</span><div><strong>Water + Fire</strong><small>A new element is waiting...</small></div><span>?</span></div><div class="recipe-item"><span>🌱 + 🌬️</span><div><strong>Earth + Air</strong><small>Try mixing the unexpected.</small></div><span>?</span></div></div></section></div>`}
 function explorePage(){return `<div class="page-title"><div><h1>Explore the Canopy</h1><p>Pick a trail, search the wild, and bring home a little wonder.</p></div><span class="pill">✦ Expedition ${STATE.explores+1}</span></div><section class="hero" style="min-height:180px;margin-bottom:17px"><div class="hero-copy"><div class="eyebrow">A living forest · 4 trails</div><h1 style="font-size:32px">The wild is calling.</h1><p>Every expedition turns up something new. Rare finds glimmer when luck is on your side.</p></div><div class="hero-art"><div class="sun"></div><div class="forest-art">🌲</div></div></section><div class="forest-grid"><button class="biome" data-emoji="💧" onclick="gather('water')"><span class="level-tag">Gather · common</span><strong>Whispering Brook</strong><span>Water · stream stones sparkle</span></button><button class="biome" data-emoji="🔥" onclick="gather('fire')"><span class="level-tag">Gather · uncommon</span><strong>Emberglow Hollow</strong><span>Fire · warmth in the roots</span></button><button class="biome" data-emoji="🪨" onclick="gather('earth')"><span class="level-tag">Gather · common</span><strong>Mosslight Grove</strong><span>Earth · the old forest floor</span></button><button class="biome" data-emoji="🌬️" onclick="gather('air')"><span class="level-tag">Gather · rare</span><strong>Cloudstep Ridge</strong><span>Air · gifts from the high canopy</span></button><button class="biome" data-emoji="🌙" onclick="gather('mystery')"><span class="level-tag">Mystery · chance</span><strong>Moonwell Clearing</strong><span>RNG · something unusual may appear</span></button><button class="biome" data-emoji="🗺️" onclick="navTo('studio')"><span class="level-tag">Community · ${STATE.customLevels.length} made</span><strong>Custom trails</strong><span>Build and play your own levels</span></button></div><div class="section-head"><div><h2>Backpack</h2><p>Gathered elements are ready to merge.</p></div><button class="text-link" onclick="navTo('merge')">Go to alchemy →</button></div><div class="element-grid">${inventoryCards()}</div>`}
