function showBoard(t){$('#boardRows').innerHTML=boardRows(t)}
function gather(place){const possible=place==='mystery'?['Water','Fire','Earth','Air']:place==='water'?['Water','Water','Air']:place==='fire'?['Fire','Fire','Earth']:place==='earth'?['Earth','Earth','Water']:['Air','Air','Water'];let chosen=possible[Math.floor(Math.random()*possible.length)];let lucky=Math.random();if(lucky>.94&&STATE.recipes&&Object.keys(STATE.recipes).length){let rare=Object.values(STATE.recipes).filter(r=>r.tier<=3);if(rare.length){let r=rare[Math.floor(Math.random()*rare.length)];chosen=r.name;toast(`Lucky find! ${r.icon} ${r.name}`)}}if(chosen==='Air'&&Math.random()>.94){STATE.coins+=6;toast('A coin glints among the leaves! +6 ◈')}STATE.inventory[chosen]=(STATE.inventory[chosen]||0)+1;STATE.discovered.add(chosen);STATE.explores++;STATE.coins+=3;STATE.xp+=4;levelCheck();render();if(!$('#toast').classList.contains('show'))toast(`Found ${getEl(chosen).icon} ${chosen}! +3 ◈`);save()}
function levelCheck(){let lvl=Math.floor(STATE.xp/500)+1;if(lvl>STATE.level){STATE.level=lvl;toast(`Level up! You reached level ${lvl}.`)}if(STATE.xp>=300)STATE.rank='Wayfinder';if(STATE.xp>=900)STATE.rank='Greenheart';if(STATE.xp>=2200)STATE.rank='Star Forager';if(STATE.xp>=4000)STATE.rank='Canopy Sage'}
function claimDaily(){const key='wildAlchemyDaily';let today=new Date().toDateString();if(localStorage.getItem(key)===today){toast('You already claimed today’s blessing.');return}localStorage.setItem(key,today);STATE.coins+=35;STATE.dust+=2;STATE.xp+=15;levelCheck();toast('Moonlit blessing: +35 coins, +2 stardust!');render();save()}
function buyItem(i){const cost=[35,55,80,40][i];if(STATE.coins<cost){toast('Not enough coins yet.');return}STATE.coins-=cost;if(i===0){STATE.playerHp=Math.min(100,STATE.playerHp+45);toast('Wild tonic: +45 HP!')}else if(i===1){STATE.dust+=3;toast('Stardust pouch opened! +3 ✧')}else if(i===2){STATE.collection.push('Mossweave cape');toast('Mossweave cape added to your collection!')}else{STATE.lucky=true;toast('Lucky acorn is ready for your next expedition!')}render();save()}
function craftItem(type){if(type==='tonic'){let items=Object.keys(STATE.inventory).filter(n=>STATE.inventory[n]>0);let amount=items.reduce((s,n)=>s+STATE.inventory[n],0);if(amount<5){toast('Gather 5 elements to craft a tonic.');return}let left=5;for(const n of items){let take=Math.min(left,STATE.inventory[n]);STATE.inventory[n]-=take;left-=take;if(!left)break}STATE.playerHp=Math.min(100,STATE.playerHp+30);toast('Canopy tonic crafted: +30 HP!')}else if(type==='charm'){let name=Object.keys(STATE.inventory).find(n=>STATE.inventory[n]>0&&getEl(n).tier===2);if(!name||STATE.dust<3){toast('Need a T2 element and 3 stardust.');return}STATE.inventory[name]--;STATE.dust-=3;STATE.collection.push('Starfall charm');toast('Starfall charm crafted!')}else{if(STATE.dust<2){toast('Need 2 stardust.');return}STATE.dust-=2;let n=BASE[Math.floor(Math.random()*4)].name;STATE.inventory[n]=(STATE.inventory[n]||0)+1;STATE.discovered.add(n);toast(`Mystery bundle: ${n}!`)}STATE.crafted++;render();save()}
function powerUp(type){let cost=type==='shield'?20:25;if(STATE.coins<cost){toast('Not enough coins.');return}STATE.coins-=cost;STATE.power=type;toast(`${type} power-up ready for the next encounter!`);render();save()}
function createElement(){let name=$('#customName').value.trim(),icon=$('#customIcon').value.trim()||'✨';if(name.length<2){toast('Give your element a name first.');return}if(allElements().some(e=>e.name.toLowerCase()===name.toLowerCase())){toast('That element name is already in your index.');return}let el={name,icon,tier:1,element:'custom',strength:$('#customStrength').value,weak:$('#customWeak').value};STATE.custom.push(el);STATE.inventory[name]=(STATE.inventory[name]||0)+1;STATE.discovered.add(name);STATE.xp+=10;levelCheck();toast(`${icon} ${name} has joined the Canopy!`);render();save()}
function createLevel(){let name=$('#levelName').value.trim()||`Trail ${STATE.customLevels.length+1}`,theme=$('#levelTheme').value,rarity=$('#levelRarity').value,icon=theme.split(' ')[0],reward=Math.max(10,Math.min(100,Number($('#levelReward').value)||30));STATE.customLevels.unshift({name,icon,rarity,theme,reward,plays:0,rank:'C'});toast(`Trail created: ${name}`);render();save()}
function playLevel(i){let l=STATE.customLevels[i];if(!l)return;l.plays++;let roll=Math.random();l.rank=roll>.75?'S':roll>.45?'A':roll>.2?'B':'C';let candidates=BASE.filter(x=>x.tier===1);let found=candidates[Math.floor(Math.random()*candidates.length)];STATE.inventory[found.name]=(STATE.inventory[found.name]||0)+1;STATE.discovered.add(found.name);STATE.coins+=l.reward;STATE.xp+=20;levelCheck();toast(`${l.rank} rank on ${l.name}! Found ${found.name}, +${l.reward} ◈`);render();save()}
function createMode(){let name=$('#modeName').value.trim()||`Wild Rules ${STATE.customModes.length+1}`,rule=$('#modeRule').value;STATE.customModes.unshift({name,rule});toast(`Gamemode “${name}” created.`);render();save()}
async function copyCode(code){try{await navigator.clipboard.writeText(code);toast('Room code copied! Send it to your friend.')}catch(e){toast(`Invite code: ${code}`)}}
function joinRoom(){let code=$('#joinCode').value.trim().toUpperCase();if(code.length<5){toast('Enter a valid friend room code.');return}toast(`Room ${code} found! Friendly challenge ready.`);STATE.customModes.unshift({name:`Room ${code}`,rule:'Friend challenge'});save()}
function setTitle(title){STATE.title=title;toast(`Title equipped: ${title}`);save()}
function setAura(aura){let cost=aura==='Stardust'?25:35;if(STATE.coins<cost){toast(`Need ${cost} coins to unlock this aura.`);return}STATE.coins-=cost;STATE.aura=aura;$('.portrait').style.boxShadow=aura==='Ember'?'0 0 22px #ff8e4c':'0 0 22px #d5f78b';toast(`${aura} aura equipped!`);render();save()}
function toggleSound(){STATE.sound=!STATE.sound;if(STATE.sound)playChime();render();save()}
function playChime(){try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[440,554,660].forEach((hz,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(.035,ctx.currentTime+i*.22);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.22+.5);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.22);o.stop(ctx.currentTime+i*.22+.52)})}catch(e){}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal').classList.add('hidden');if(e.key.toLowerCase()==='m'&&STATE.page!=='merge')navTo('merge')});
// Harmless local cheat codes, entered with the ? key on any page.
document.addEventListener('keydown',e=>{if(e.key==='?')openCheats()});
function openCheats(){$('#modal-box').innerHTML=`<h2>Forest whispers</h2><p>A few secret phrases for a playful boost. Codes work on this save only.</p><input class="input" id="cheatInput" placeholder="Enter a cheat code"><div class="modal-actions"><button class="button secondary" onclick="$('#modal').classList.add('hidden')">Close</button><button class="button" onclick="applyCheat()">Whisper</button></div>`;$('#modal').classList.remove('hidden')}
function applyCheat(){let code=$('#cheatInput').value.trim().toLowerCase();if(code==='leafmealone'){STATE.coins+=500;STATE.dust+=20;toast('The forest giggles. +500 coins, +20 stardust!')}else if(code==='wildthings'){for(const e of BASE){STATE.inventory[e.name]=(STATE.inventory[e.name]||0)+10;STATE.discovered.add(e.name)}toast('The forest is generous. +10 of every element!')}else if(code==='moonrise'){STATE.xp+=500;STATE.level+=1;levelCheck();toast('Moonrise! +500 renown.')}else{toast('No answer from the forest. Try another whisper.')}$('#modal').classList.add('hidden');render();save()}
load();if(localStorage.getItem('wildAlchemySave')){STATE.discovered=new Set(STATE.discovered);$('#welcome').classList.remove('hidden')}
</script>
</body>
</html>

