coveries. Combine any pair of T2 elements to create T3, then continue all the way to T5.</div><div class="recipe-list">${Object.values(STATE.recipes).slice(-12).reverse().map(r=>`<div class="recipe-item"><span style="font-size:22px">${r.icon}</span><div><strong>${safe(r.name)} <small>· T${r.tier}</small></strong><small>${r.parents.map(safe).join(' + ')}</small></div><b style="margin-left:auto">${STATE.inventory[r.name]||0}</b></div>`).join('')||'<div class="notice">Your first combination is waiting.</div>'}</div></section></div>`}
 function doMerge(){if(STATE.selected.length!==2)return;const [a,b]=STATE.selected,ea=getEl(a),eb=getEl(b);if(ea.tier!==eb.tier){toast('Those tiers cannot be merged together.');return}if((STATE.inventory[a]||0)<(a===b?2:1)||(STATE.inventory[b]||0)<1){toast('You need two copies to merge an element with itself.');return}if(ea.tier>=5){toast('Tier 5 is the final tier.');return}STATE.inventory[a]--;STATE.inventory[b]--;const r=makeRecipe(a,b);if(!r){toast('Tier 5 is the final tier.');return}STATE.inventory[r.name]=(STATE.inventory[r.name]||0)+1;STATE.discovered.add(r.name);STATE.crafted++;STATE.coins+=8;STATE.xp+=25;STATE.selected=[];levelCheck();toast(`Discovery! ${r.icon} ${r.name} · Tier ${r.tier}`);render();save()}
 function indexPage(){let els=allElements().filter(e=>STATE.discovered.has(e.name));return `<div class="page-title"><div><h1>Field index</h1><p>A living record of the elements discovered across the Canopy.</p></div><span class="pill">${els.length} discovered · ${allElements().length} known</span></div><div class="notice">All possible pair recipes are generated as you go: each pair within a tier makes its own unique next-tier element. Tier ${Math.min(5,Math.max(1,...els.map(e=>e.tier)))} of 5.</div>${[1,2,3,4,5].map(t=>`<div class="tier-label">Tier ${t} · ${els.filter(e=>e.tier===t).length} discovered</div><div class="element-grid">${els.filter(e=>e.tier===t).map(e=>`<div class="element-card"><div class="el-emoji">${e.icon}</div><strong>${safe(e.name)}</strong><small>${e.custom?'Custom creation':e.recipe?`${safe(e.recipe.parents.join(' + '))}`:`${e.element} · ${e.strength||'wild'}`}</small>${STATE.inventory[e.name]?`<span class="count">${STATE.inventory[e.name]}</span>`:''}</div>`).join('')||'<div class="notice">Not discovered yet. Keep exploring and combining!</div>'}</div>`).join('')}<div class="section-head"><div><h2>Recipe branches</h2><p>Unique combinations discovered so far.</p></div></div><div class="recipe-list">${Object.values(STATE.recipes).map(r=>`<div class="recipe-item"><span>${r.icon}</span><div><strong>${safe(r.name)} · Tier ${r.tier}</strong><small>${r.parents.map(safe).join(' + ')}</small></div></div>`).join('')||'<div class="notice">No recipes yet. The first pair is yours to discover.</div>'}</div>`}
 function battlePage(){const hp=Math.max(0,STATE.bossHp),php=Math.max(0,STATE.playerHp);return `<div class="page-title"><div><h1>Boss grove</h1><p>Choose an element before the encounter. Strengths and weaknesses change the tide.</p></div><span class="pill">⚔ ${STATE.wins} victories</span></div><div class="battlefield"><div class="fighter"><div class="big">🧙</div><strong>Fern Walker</strong><div class="hp player"><i style="width:${php}%"></i></div><small>${php} / 100 HP · ${STATE.selected[0]?safe(STATE.selected[0]):'no element selected'}</small></div><div style="font-size:24px;color:#edc879;z-index:1">VS</div><div class="fighter"><div class="big">${STATE.levelNo%3===0?'🐉':STATE.levelNo%3===1?'🦉':'🦌'}</div><strong>${STATE.levelNo%3===0?'Elder Bramblewing':STATE.levelNo%3===1?'Gloamroot Guardian':'Moonhart'}</strong><div class="hp"><i style="width:${hp}%"></i></div><small>${hp} / 100 HP · Weak to ${['water','air','fire'][(STATE.levelNo-1)%3]}</small></div></div><div class="battle-log" id="battlelog">${php<=0?'Catch your breath before facing the grove again.':'The grove waits. Pick a discovered element, then take your turn.'}</div><div class="section-head"><div><h2>Choose your attunement</h2><p>Strengths deal bonus damage; weaknesses are less effective.</p></div></div><div class="element-grid">${inventoryCards()}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="button" onclick="battleTurn()">⚔ Take your turn</button><button class="button secondary" onclick="restBattle()">✦ Rest · 10 ◈</button></div><div class="notice">Element cycle: Water > Fire > Air > Earth > Water. Battle is turn-based; the rival grove responds after every action.</div>`}
