 function forgePage(){return `<div class="page-title"><div><h1>Moonlit forge</h1><p>Trade your finds for little things that make adventures brighter.</p></div><span class="pill">◈ ${STATE.coins} coins · ✧ ${STATE.dust} stardust</span></div><div class="two-col"><section class="content-card"><h2 style="font:23px Georgia,serif">Canopy market</h2><p style="color:var(--muted);font-size:11px">A few wares, all made with care.</p><div class="level-list">${[['🧪','Wild tonic','Restore your health before a boss fight.',35],['✨','Stardust pouch','A pinch of glitter for the crafting table.',55],['🧥','Mossweave cape','A charming forest look.',80],['🔮','Lucky acorn','A little extra luck on your next expedition.',40]].map(([i,n,d,c],idx)=>`<div class="level-item"><span class="emoji">${i}</span><div><strong>${n}</strong><small>${d}</small></div><button class="mini-button" onclick="buyItem(${idx})">${c} ◈</button></div>`).join('')}</div></section><section class="content-card"><h2 style="font:23px Georgia,serif">Crafting nook</h2><p style="color:var(--muted);font-size:11px">Turn spare discoveries into useful things.</p><div class="level-list"><div class="level-item"><span class="emoji">🧴</span><div><strong>Canopy tonic</strong><small>5 elements · restore 30 HP</small></div><button class="mini-button" onclick="craftItem('tonic')">Craft</button></div><div class="level-item"><span class="emoji">🌟</span><div><strong>Starfall charm</strong><small>1 T2 element · 3 stardust</small></div><button class="mini-button" onclick="craftItem('charm')">Craft</button></div><div class="level-item"><span class="emoji">🎁</span><div><strong>Mystery bundle</strong><small>2 stardust · a random element</small></div><button class="mini-button" onclick="craftItem('bundle')">Craft</button></div></div><div class="notice">Crafting recipes use your gathered inventory. Explore to stock up, or merge for rare materials.</div></section></div><div class="section-head"><div><h2>Power-ups</h2><p>One-time boosts for your next battle.</p></div></div><div class="forest-grid"><div class="card"><div style="font-size:27px">🛡️</div><b style="font-size:12px">Barkskin</b><p style="font-size:10px;color:var(--muted)">A sturdy shield against the next boss hit.</p><button class="mini-button" onclick="powerUp('shield')">Make · 20 ◈</button></div><div class="card"><div style="font-size:27px">⚡</div><b style="font-size:12px">Quickstep</b><p style="font-size:10px;color:var(--muted)">Add a burst of damage in the next fight.</p><button class="mini-button" onclick="powerUp('quickstep')">Make · 25 ◈</button></div><div class="card"><div style="font-size:27px">🍀</div><b style="font-size:12px">Lucky charm</b><p style="font-size:10px;color:var(--muted)">Improve your chance at a rare find.</p><button class="mini-button" onclick="powerUp('luck')">Make · 25 ◈</button></div></div>`}
